-- Subconjunto del dump herencia_database V1.0.2 (adaptado a MariaDB para las pruebas)
SET FOREIGN_KEY_CHECKS=0;
CREATE TABLE `categoria` (`id_categoria` int NOT NULL AUTO_INCREMENT,`nombre_categoria` varchar(100) NOT NULL,`descripcion` varchar(100) DEFAULT NULL,PRIMARY KEY (`id_categoria`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT INTO `categoria` VALUES (1,'Dulces de leche','Arequipe, manjar blanco, cocadas'),(2,'Bocadillos','Bocadillo veleño y de guayaba'),(3,'Panadería típica','Pandebono, rosquillas, galletas');
CREATE TABLE `clientes` (`id_clientes` int NOT NULL AUTO_INCREMENT,`identificacion` int NOT NULL,`nombre_cliente` varchar(45) NOT NULL,`apellido_cliente` varchar(45) DEFAULT NULL,`telefono_clientes` varchar(45) DEFAULT NULL,`correo_clientes` varchar(45) DEFAULT NULL,`direccion_clientes` varchar(255) DEFAULT NULL,`ciudad_clientes` varchar(45) DEFAULT NULL,PRIMARY KEY (`id_clientes`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT INTO `clientes` VALUES (1,1109665804,'prueba ','prueba','3184003720','prueba@gmail.com',NULL,NULL);
CREATE TABLE `metodo_pago` (`id_metodopago` int NOT NULL AUTO_INCREMENT,`metodo_pago` varchar(100) NOT NULL,PRIMARY KEY (`id_metodopago`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT INTO `metodo_pago` VALUES (1,'efectivo'),(2,'tarjeta debito'),(3,'tarjeta credito'),(4,'transferencia'),(5,'nequi'),(6,'credito');
CREATE TABLE `ingreso_mercancia` (`id_entrada` int NOT NULL AUTO_INCREMENT,`codigo_entrada` varchar(20) DEFAULT NULL,`fecha` date DEFAULT NULL,`subtotal` decimal(12,2) DEFAULT NULL,`iva` decimal(12,2) DEFAULT NULL,`total` decimal(12,2) DEFAULT NULL,`observacion` varchar(255) DEFAULT NULL,PRIMARY KEY (`id_entrada`),UNIQUE KEY `codigo_entrada_UNIQUE` (`codigo_entrada`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE `det_entrada` (`id_det_entrada` int NOT NULL AUTO_INCREMENT,`fk_det_entrada_id_entrada` int DEFAULT NULL,`fk_det_entrada_id_producto` int DEFAULT NULL,`cantidad` int DEFAULT NULL,`precio_unitario` decimal(12,2) DEFAULT NULL,`subtotal` decimal(12,2) DEFAULT NULL,`iva` decimal(12,2) DEFAULT NULL,`total` decimal(12,2) DEFAULT NULL,PRIMARY KEY (`id_det_entrada`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE `salida_mercancia` (`id_salida` int NOT NULL AUTO_INCREMENT,`codigo_salida` varchar(50) DEFAULT NULL,`fecha` date DEFAULT NULL,`subtotal` decimal(12,2) DEFAULT NULL,`iva` decimal(12,2) DEFAULT NULL,`total` decimal(12,2) DEFAULT NULL,`observacion` varchar(250) NOT NULL,PRIMARY KEY (`id_salida`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE `det_salida` (`id_det_salida` int NOT NULL AUTO_INCREMENT,`fk_det_salida_id_salida` int NOT NULL,`fk_det_salida_id_producto` int NOT NULL,`cantidad` int DEFAULT NULL,`precio_unitario` decimal(12,2) DEFAULT NULL,`subtotal` decimal(12,2) DEFAULT NULL,`total` decimal(12,2) DEFAULT NULL,PRIMARY KEY (`id_det_salida`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE `producto` (`id_producto` int NOT NULL AUTO_INCREMENT,`codigo_producto` varchar(50) NOT NULL,`nombre_producto` varchar(150) NOT NULL,`stock` int NOT NULL,`costo_produccion` decimal(10,2) DEFAULT NULL,`precio_venta` decimal(10,2) DEFAULT NULL,`iva` decimal(5,2) DEFAULT NULL,`fecha_produccion` date DEFAULT NULL,`fecha_vencimiento` date DEFAULT NULL,`fk_producto_id_categoria` int DEFAULT NULL,`deleted_at` datetime DEFAULT NULL,PRIMARY KEY (`id_producto`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE `proovedores` (`id_proovedores` int NOT NULL AUTO_INCREMENT,`nit` int NOT NULL,`razon_social` varchar(100) NOT NULL,`telefono_proovedor` varchar(45) NOT NULL,`dirreccion` varchar(45) NOT NULL,`ciudad` varchar(45) NOT NULL,PRIMARY KEY (`id_proovedores`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT INTO `proovedores` VALUES (1,900123456,'Lácteos del Valle SAS','3104567890','Cra 5 # 10-20','Palmira');
CREATE TABLE `proveedor_producto` (`id_proveedor_producto` int NOT NULL AUTO_INCREMENT,`fk_producto-proovedor_id_proovedor` int NOT NULL,`fk_producto-proovedor_id_producto` int NOT NULL,`precio_compra` decimal(10,2) NOT NULL,`cantidad_minima` int DEFAULT NULL,`tiempo_entrega` int DEFAULT NULL,`fecha_suministro` date DEFAULT NULL,PRIMARY KEY (`id_proveedor_producto`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE `rol` (`idrol` int NOT NULL,`nombre_rol` varchar(100) DEFAULT NULL,`descripcion` varchar(100) DEFAULT NULL,PRIMARY KEY (`idrol`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT INTO `rol` VALUES (1,'admin','administrador');
CREATE TABLE `usuario` (`idusuario` int NOT NULL AUTO_INCREMENT,`nombre_usuario` varchar(100) DEFAULT NULL,`apellido_usuario` varchar(100) DEFAULT NULL,`correo_usuario` varchar(150) DEFAULT NULL,`contraseña_usuario` varchar(255) DEFAULT NULL,`telefono_usuario` varchar(20) DEFAULT NULL,`fk_usuario_id_rol` int NOT NULL,PRIMARY KEY (`idusuario`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE `venta` (`id_venta` int NOT NULL AUTO_INCREMENT,`total` decimal(10,2) NOT NULL,`numero_venta` varchar(20) NOT NULL,`fecha` date NOT NULL,`fk_venta_id_cliente` int DEFAULT NULL,`fk_venta_id_usuario` int DEFAULT NULL,`subtotal` decimal(10,2) NOT NULL,`iva` decimal(10,2) NOT NULL,`descuento` decimal(10,2) DEFAULT NULL,PRIMARY KEY (`id_venta`),UNIQUE KEY `numero_venta_UNIQUE` (`numero_venta`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE `det_venta` (`id_detalleventa` int NOT NULL AUTO_INCREMENT,`fk_det_venta_id_venta` int NOT NULL,`fk_det_venta_id_producto` int NOT NULL,`cantidad` int NOT NULL,`precio_venta` decimal(10,2) NOT NULL,`iva_producto` decimal(5,2) NOT NULL,`subtotal` decimal(10,2) NOT NULL,`total` decimal(10,2) NOT NULL,PRIMARY KEY (`id_detalleventa`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE `lote` (`id_lote` int NOT NULL AUTO_INCREMENT,`fk_lote_id_producto` int NOT NULL,`numero_lote` varchar(50) NOT NULL,`cantidad_inicial` int NOT NULL,`cantidad_actual` int NOT NULL,`fecha_produccion` date DEFAULT NULL,`fecha_vencimiento` date NOT NULL,`fk_lote_id_ingreso` int DEFAULT NULL,`created_at` datetime DEFAULT NULL,PRIMARY KEY (`id_lote`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE `det_venta_lote` (`id_det_venta_lote` int NOT NULL AUTO_INCREMENT,`fk_det_venta_lote_id_detalleventa` int NOT NULL,`fk_det_venta_lote_id_lote` int NOT NULL,`cantidad_tomada` int NOT NULL,PRIMARY KEY (`id_det_venta_lote`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
SET FOREIGN_KEY_CHECKS=1;
